+export const join = mutationGeneric({
+  args: { portalSecret: v.string(), email: v.string(), product: v.string(), intent: v.string(), offerId: v.string() },
+  returns: v.null(),
+  handler: async (ctx, args) => {
+    requirePortalSecret(args.portalSecret);
+    const input = purchaseWaitlistSchema.parse(args);
+    const existing = await ctx.db.query("purchaseWaitlist")
+      .withIndex("by_request", q => q.eq("email", input.email).eq("product", input.product).eq("intent", input.intent).eq("offerId", input.offerId)).unique();
+    if (existing) await ctx.db.patch(existing._id, { updatedAt: Date.now() });
+    else await ctx.db.insert("purchaseWaitlist", { ...input, createdAt: Date.now(), updatedAt: Date.now() });
+    return null;
+  },
+});
